-- mod-kill-collector: the token shop's class buffs as spells of their own. GENERATED by tools/gen_shop_buffs.py; do not edit.
--
-- spell_dbc: one row per shop buff, ids 2032000-2032067 (vault 06-custom-ids.md, band 2032000-2032099): a copy of the class buff's top-rank
-- row with every amount x1.5, one hour (SpellDuration index 42), a self buff, no cost or cooldown, no spell family,
-- rank text 'Empowered'.
-- spell_group / spell_group_stack_rules: the copy joins the EXCLUSIVE_HIGHEST group(s) its original sits in; the groups
-- 2300000-2300399 each hold one spell's first rank + the copy where no such group covers it, so a normal cast of the
-- original on someone holding the copy fails with 'A more powerful spell is already active'. The client rows come
-- from fl-pipeline 214_token_shop_buff_spells.py (patch-9); the shop itself is fl-lua-scripts TokenShop/.
-- Idempotent: the DELETEs name exactly the keys the INSERTs write.

DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 2032000 AND 2032099;

DELETE FROM `spell_group` WHERE `spell_id` BETWEEN 2032000 AND 2032099 OR `id` BETWEEN 2300000 AND 2300399;

DELETE FROM `spell_group_stack_rules` WHERE `group_id` BETWEEN 2300000 AND 2300399;
